all(".art-card").forEach((card) => card.onclick = () => {
  const slug = card.dataset.art;
  one("#artImage").src = "assets/art/posters/" + slug + ".png";
  one("#artImage").alt = card.dataset.artTitle;
  one("#artName").textContent = card.dataset.artTitle;
  one("#artDialog").showModal();
});
one("#closeArt").onclick = () => one("#artDialog").close();
one("#closeEvidence").onclick = () => {
  one("#evidenceDrawer").close();
  one("#evidenceFrame").removeAttribute("src");
  if (evidenceBlobUrl) { URL.revokeObjectURL(evidenceBlobUrl); evidenceBlobUrl = ""; }
};
addEventListener("hashchange", () => {
  if (location.hash === "" || location.hash === "#") {
    one("#readerView").classList.add("hidden");
    one("#homeView").classList.remove("hidden");
  }
});
setLanguage(lang);
loadEvidence();
init().catch((error) => { one("#main").innerHTML = '<p style="padding:3rem">Could not load the book. ' + error.message + "</p>"; });
